DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='warranty_claim_contact_log'; d:=replace(d,'WHERE warranty_claim_id=NEW.id','WHERE warranty_claim_id=NEW.id AND external_customer IS NOT NULL'); EXECUTE d;
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='voertuig_werkhistorie'; d:=replace(d,'''claim_status'', c.claim_status','''claim_status'', c.claim_status, ''claim_nummer'', c.claim_nummer'); EXECUTE d;
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='voertuig_tijdlijn'; d:=replace(d,'''Garantieclaim aangemaakt'', c.description','''Garantieclaim '' || c.claim_nummer || '' aangemaakt'', c.description'); d:=replace(d,'''Garantieclaim opgelost'', c.resolution_description','''Garantieclaim '' || c.claim_nummer || '' opgelost'', c.resolution_description'); EXECUTE d;
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='voertuig_open_punten'; d:=replace(d,'me.details->>''deliveryAppointment''','me.details->>''deliveryAppointmentDate'''); d:=replace(d,'IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN(''owner'',''admin'',''aftersales_manager'',''werkplaats_chef'',''operationeel_directeur'',''administratie'')) THEN','IF public.has_role(auth.uid(),''owner'') OR public.has_role(auth.uid(),''admin'') OR public.has_role(auth.uid(),''aftersales_manager'') OR public.has_role(auth.uid(),''werkplaats_chef'') OR public.has_role(auth.uid(),''operationeel_directeur'') OR public.has_role(auth.uid(),''administratie'') THEN'); d:=replace(d,'w.origin=''extern''','(w.origin=''extern'' OR w.external_customer IS NOT NULL)'); EXECUTE d;
END $$;